import { Mesh, PlaneGeometry, Object3D, Vector3, Euler, Texture, Group } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createTextMesh } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string, depthMapUrl?:string, meshUrl?:string}} assets
 * @property {{position: [number, number, number], rotation: [number, number, number], scale: [number, number, number]}} placement
 * @property {Array<{name:string, params:any}>} cinematicPrimitives
 * @property {string} textContent
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Promise<Texture>} textureLoader
 * @property {{[key:string]:(obj:Object3D, params:any)=>void}} primitives
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{emit:(event:string, payload?:any)=>void}} eventBus
 */

/**
 * Create a journal card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {Object3D}
 */
export default function createNode(config, ctx) {
    // root container
    const root = new Group();
    root.name = 'journal-card-2-label';

    // -------------------------------------------------
    // Geometry & Material
    // -------------------------------------------------
    const geometry = new PlaneGeometry(1, 1, 1, 1);
    const material = new MeshBasicNodeMaterial();

    // load texture synchronously via cached loader
    const texture = ctx.textureLoader(config.assets.imageUrl);
    if (texture instanceof Promise) {
        // texture loader may return a promise; ensure sync by using resolved texture if already cached
        texture.then(t => material.map = t);
    } else {
        material.map = /** @type {Texture} */ (texture);
    }
    material.transparent = true;
    material.depthWrite = false;

    const plane = new Mesh(geometry, material);
    plane.name = 'card-plane';
    root.add(plane);

    // -------------------------------------------------
    // Position / Rotation / Scale
    // -------------------------------------------------
    const [px, py, pz] = config.placement.position;
    const [rx, ry, rz] = config.placement.rotation;
    const [sx, sy, sz] = config.placement.scale;

    root.position.set(px, py, pz);
    root.rotation.set(rx, ry, rz);
    root.scale.set(sx, sy, sz);

    // -------------------------------------------------
    // Text overlay (MSDF)
    // -------------------------------------------------
    if (config.textContent) {
        const textMesh = createTextMesh({
            text: config.textContent,
            fontAtlas: ctx.fontAtlas,
            // design token hints
            color: '#16161d', // ink
            fontSize: 0.13, // using body scale as approximate scene unit
            // atlas region (placeholder, uses whole atlas)
            atlasRegion: { x: 0, y: 0, width: 512, height: 320 }
        });
        // Position text slightly above plane surface
        textMesh.position.set(0, 0, 0.001);
        // Preserve same scaling as plane
        textMesh.scale.set(0.9, 0.9, 0.9);
        root.add(textMesh);
    }

    // -------------------------------------------------
    // Cinematic primitives
    // -------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const apply = ctx.primitives[prim.name];
            if (typeof apply === 'function') {
                apply(root, prim.params);
            }
        }
    }

    // -------------------------------------------------
    // Interaction handlers
    // -------------------------------------------------
    const hoverTimeline = gsap.timeline({ paused: true });
    hoverTimeline.to(root.position, {
        y: root.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out'
    });

    const pressTimeline = gsap.timeline({ paused: true });
    pressTimeline.to(root.scale, {
        x: root.scale.x * 0.97,
        y: root.scale.y * 0.97,
        z: root.scale.z * 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)'
    });

    root.userData.handlers = {};

    root.userData.handlers.pointerover = () => {
        hoverTimeline.restart();
    };
    root.userData.handlers.pointerout = () => {
        hoverTimeline.reverse();
    };
    root.userData.handlers.pointerdown = () => {
        pressTimeline.restart();
    };
    root.userData.handlers.pointerup = () => {
        pressTimeline.reverse();
        // emit navigation event on click release
        ctx.eventBus.emit('hub-journal.select', { source: 'journal-card-2' });
    };

    // -------------------------------------------------
    // Cleanup
    // -------------------------------------------------
    root.userData.cleanup = () => {
        hoverTimeline.kill();
        pressTimeline.kill();
        geometry.dispose();
        material.dispose();
        if (material.map) {
            material.map.dispose();
        }
        // dispose text mesh resources if present
        root.traverse(child => {
            if (child.isMesh && child !== plane) {
                if (child.material) child.material.dispose();
                if (child.geometry) child.geometry.dispose();
            }
        });
    };

    return root;
}
